CREATE OR REPLACE FUNCTION public.agendar_comissao_217(_comissao uuid, _valor numeric, _vencimento date, _chave uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.comissoes; conta uuid; parcela uuid; limite numeric;
begin
 if not public.pode_rotina('comissao_proporcional_operar') or not public.can_finance(auth.uid()) then raise exception 'Sem acesso à comissão proporcional'; end if;
 select * into c from public.comissoes where id=_comissao for update;
 if c.id is null or not public.usuario_pode_acessar_centro(c.centro_id) or (public.escopo_representante() and c.representante_id is distinct from public.meu_representante_id()) then raise exception 'Comissão sem acesso'; end if;
 if _valor is null or _valor<=0 or _valor::text in ('NaN','Infinity','-Infinity') or _vencimento is null or _chave is null then raise exception 'Valor, vencimento e chave obrigatórios'; end if;
 select cp.id into parcela from public.comissao_parcelas cp join public.contas_pagar t on t.id=cp.conta_pagar_id where cp.chave=_chave and cp.comissao_id=c.id and cp.valor=round(_valor,2) and t.vencimento=_vencimento;
 if parcela is not null then return parcela; end if;
 if exists(select 1 from public.comissao_parcelas where chave=_chave) then raise exception 'Chave já usada com dados diferentes'; end if;
 limite:=public.comissao_disponivel_217(c.id);
 if round(_valor,2)>limite then raise exception 'Valor excede comissão disponível após recebimentos (%).',limite; end if;
 insert into public.contas_pagar(centro_id,documento,parcela,valor,vencimento,data_emissao,status,descricao)
 values(c.centro_id,'CP-'||left(_chave::text,8),1,round(_valor,2),_vencimento,current_date,'aberto','Comissão proporcional do pedido '||c.pedido_id) returning id into conta;
 insert into public.comissao_parcelas(comissao_id,conta_pagar_id,valor,chave) values(c.id,conta,round(_valor,2),_chave) returning id into parcela;
 insert into public.auditoria(tabela,registro_id,acao,user_id,detalhe) values('comissoes',c.id,'agendar_proporcional',auth.uid(),jsonb_build_object('conta_pagar',conta,'valor',_valor));
 return parcela;
end $function$
CREATE OR REPLACE FUNCTION public.trg_apurar_comissao_pedido()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 if public.ajuste_status_manual_ativo_269(new.id) then return new;end if;
  perform public.apurar_comissao_pedido(new.id);
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.apurar_comissao_pedido(_pedido_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.pedidos; c public.comissoes; base numeric; valor_base numeric; devolvido numeric; corrigida numeric; st text; recebida boolean;
begin
 -- orcamento_comissao_236
 if exists(select 1 from public.pedidos q236 where q236.id=_pedido_id and q236.tipo_documento='orcamento') then return; end if;

 select * into p from public.pedidos where id=_pedido_id for update;
 if p.id is null then return; end if;
 if auth.uid() is not null and (not public.usuario_ativo() or not public.usuario_pode_acessar_centro(p.centro_id) or
  (public.escopo_representante() and not public.documento_na_minha_carteira('pedidos',p.id))) then raise exception 'Pedido sem acesso para apurar comissão'; end if;
 select * into c from public.comissoes where pedido_id=p.id for update;
 if c.status='paga' then return; end if;
 if p.representante_id is null then
  delete from public.comissoes where pedido_id=p.id and status in ('prevista','cancelada'); return;
 end if;
 if p.status in ('rascunho','digitacao','aguardando_aprovacao','aprovado') then
  base:=greatest(coalesce(p.total_itens,0)-coalesce(p.desconto_valor,0),0);
  valor_base:=coalesce(p.comissao_valor,round(base*coalesce(p.comissao_percentual,0)/100,2));
 else
  base:=coalesce(c.base_original,greatest(coalesce(p.total_itens,0)-coalesce(p.desconto_valor,0),0));
  valor_base:=coalesce(c.valor_original,p.comissao_valor,0);
 end if;
 select coalesce(sum(valor_total),0) into devolvido from public.devolucoes where pedido_id=p.id and status='confirmada';
 corrigida:=round(valor_base*case when base>0 then greatest(base-devolvido,0)/base else 0 end,2);
 recebida:=p.total_liquido>0 and
  coalesce((select sum(least(t.valor,coalesce(t.valor_pago,0))) from public.contas_receber t where t.pedido_id=p.id and (t.status<>'cancelado' or exists(select 1 from public.renegociacao_origens ro where ro.titulo_id=t.id))),0)+
  coalesce((select sum(a.valor) from public.creditos_clientes_aplicacoes a where a.pedido_id=p.id and a.status='aplicado'),0)>=p.total_liquido-0.009;
 st:=case when p.status in ('cancelado','recusado') then 'cancelada'
  when p.status in ('faturado','em_rota','entregue','parcial') and
    ((select regra.valor from public.parametros_da_loja_243((select centro_id from public.pedidos where id=_pedido_id)) regra where regra.chave='comissao_fato_gerador')='venda' or recebida) then 'liberada'
  when c.status='liberada' then 'liberada' else 'prevista' end;
 if c.id is null then
  insert into public.comissoes(representante_id,pedido_id,base_calculo,percentual,valor,status,centro_id,base_original,valor_original)
  values(p.representante_id,p.id,greatest(base-devolvido,0),coalesce(p.comissao_percentual,0),corrigida,st,p.centro_id,base,valor_base);
 else
  update public.comissoes set representante_id=p.representante_id,base_calculo=greatest(base-devolvido,0),percentual=coalesce(p.comissao_percentual,0),valor=corrigida,
   status=st,centro_id=coalesce(c.centro_id,p.centro_id),base_original=base,valor_original=valor_base where id=c.id;
 end if;
end $function$
CREATE OR REPLACE FUNCTION public.liberar_comissoes(_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if not public.can_finance(auth.uid()) then
    raise exception 'Sem permissao para liberar comissoes';
  end if;
  update public.comissoes
     set status = 'liberada'
   where id = any(_ids) and status = 'prevista';
  get diagnostics n = row_count;
  return n;
end;
$function$
CREATE OR REPLACE FUNCTION public.pagar_comissoes(_representante_id uuid, _comissao_ids uuid[], _vencimento date DEFAULT CURRENT_DATE, _categoria_id uuid DEFAULT NULL::uuid, _conta_id uuid DEFAULT NULL::uuid, _forma_id uuid DEFAULT NULL::uuid, _observacao text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  lote_id uuid;
  conta_id uuid;
  total numeric(14,2);
  qtd integer;
  centro uuid;
  ini date;
  fim date;
  rep_nome text;
BEGIN
 -- proporcional_217
 if not public.usuario_ativo() or not public.can_finance(auth.uid()) then raise exception 'Sem acesso a comissões'; end if;
 perform 1 from public.comissoes where id=any(_comissao_ids) order by id for update;
 if exists(select 1 from public.comissao_parcelas cp join public.contas_pagar t on t.id=cp.conta_pagar_id where cp.comissao_id=any(_comissao_ids) and t.status<>'cancelado') then raise exception 'Use pagamento proporcional para comissões com parcelas já agendadas'; end if;
  if not public.can_finance(auth.uid()) then
    raise exception 'Sem permissao para pagar comissoes';
  end if;

  if _comissao_ids is null or cardinality(_comissao_ids) = 0 then
    raise exception 'Nenhuma comissao selecionada';
  end if;

  -- Serializa pagamentos concorrentes das mesmas comissoes.
  perform 1
  from public.comissoes cm
  where cm.id = any(_comissao_ids)
    and cm.representante_id = _representante_id
    and cm.status in ('prevista','liberada')
  for update;

  select coalesce(sum(cm.valor), 0), count(*), min(cm.centro_id),
         min(coalesce(p.data_pedido, cm.created_at::date)),
         max(coalesce(p.data_pedido, cm.created_at::date))
    into total, qtd, centro, ini, fim
  from public.comissoes cm
  left join public.pedidos p on p.id = cm.pedido_id
  where cm.id = any(_comissao_ids)
    and cm.representante_id = _representante_id
    and cm.status in ('prevista','liberada');

  if coalesce(qtd, 0) = 0 then
    raise exception 'Nenhuma comissao elegivel selecionada';
  end if;
  if total <= 0 then
    raise exception 'Valor total das comissoes deve ser maior que zero';
  end if;

  -- Todas as comissoes do lote devem pertencer ao mesmo centro.
  if exists (
    select 1
    from public.comissoes cm
    where cm.id = any(_comissao_ids)
      and cm.representante_id = _representante_id
      and cm.status in ('prevista','liberada')
      and cm.centro_id is distinct from centro
  ) then
    raise exception 'As comissoes selecionadas pertencem a centros diferentes';
  end if;

  if not public.usuario_pode_acessar_centro(centro) then
    raise exception 'Usuario sem acesso ao centro das comissoes';
  end if;

  if _conta_id is not null and not exists (
    select 1 from public.contas_financeiras cf
    where cf.id = _conta_id
      and public.usuario_pode_acessar_centro(cf.centro_id)
      and cf.centro_id is not distinct from centro
  ) then
    raise exception 'Conta financeira invalida ou de outro centro';
  end if;

  select nome into rep_nome from public.representantes where id = _representante_id;

  insert into public.contas_pagar
    (fornecedor_id, documento, parcela, valor, vencimento, data_emissao, status,
     centro_id, categoria_id, forma_pagamento_id, conta_financeira_id, descricao, observacao)
  values
    (null, null, 1, total, coalesce(_vencimento, current_date), current_date, 'aberto',
     centro, _categoria_id, _forma_id, _conta_id,
     'Comissao ' || coalesce(rep_nome, 'representante') ||
       ' (' || to_char(coalesce(ini, current_date), 'DD/MM/YYYY') || ' a ' ||
       to_char(coalesce(fim, current_date), 'DD/MM/YYYY') || ')',
     _observacao)
  returning id into conta_id;

  insert into public.comissao_pagamentos
    (representante_id, centro_id, competencia, periodo_inicio, periodo_fim,
     quantidade, valor_total, conta_pagar_id, vencimento, observacao, created_by)
  values
    (_representante_id, centro, to_char(coalesce(fim, current_date), 'YYYY-MM'), ini, fim,
     qtd, total, conta_id, coalesce(_vencimento, current_date), _observacao, auth.uid())
  returning id into lote_id;

  insert into public.comissao_pagamento_itens (pagamento_id, comissao_id, valor)
  select lote_id, cm.id, cm.valor
  from public.comissoes cm
  where cm.id = any(_comissao_ids)
    and cm.representante_id = _representante_id
    and cm.status in ('prevista','liberada');

  update public.comissoes
     set status = 'paga'
   where id in (select comissao_id from public.comissao_pagamento_itens where pagamento_id = lote_id);

  return lote_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.modalidade_pedido_296()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare conversao boolean:=false;begin
 if new.modalidade_venda='intermediacao' and new.tipo_documento not in('pedido','orcamento') then raise exception 'Modalidade indisponível neste documento';end if;
 if new.modalidade_venda='intermediacao' and (tg_op='INSERT' or old.modalidade_venda is distinct from new.modalidade_venda) then
  if not public.intermediacao_ativa_296(new.centro_id) or new.status not in('rascunho','digitacao') then raise exception 'Intermediação não habilitada nesta loja ou documento indisponível';end if;
  if new.tipo_documento='orcamento' and (not public.pode_rotina('pedidos_orcamentos') or new.orcamento_situacao is distinct from 'negociacao' or new.orcamento_data is null or new.orcamento_validade is null or new.orcamento_validade<(now() at time zone 'America/Sao_Paulo')::date) then raise exception 'Orçamento sem acesso ou fora da negociação válida';end if;
 end if;
 if tg_op='UPDATE' then
  conversao:=old.tipo_documento='orcamento' and new.tipo_documento='pedido' and old.orcamento_situacao='negociacao' and new.orcamento_situacao='aceito' and new.orcamento_aceito_em is not null and old.orcamento_data is not null;
  /* vendedor_modalidade_298 */ if tg_op='UPDATE' and new.modalidade_venda is distinct from old.modalidade_venda and old.modalidade_venda='intermediacao' and not public.vendedor_intermediacao_autorizado_298(old.centro_id) then raise exception 'Vendedor não autorizado para intermediação';end if;
 if new.modalidade_venda is distinct from old.modalidade_venda and (old.status not in('rascunho','digitacao') or exists(select 1 from public.pedido_itens where pedido_id=old.id) and not public.contexto_modalidade_298(old.id)) then raise exception 'Use a prévia para alterar a modalidade com itens';end if;
  if old.modalidade_venda='intermediacao' and exists(select 1 from public.pedido_itens where pedido_id=old.id) and (
   new.centro_id is distinct from old.centro_id or
   coalesce(new.orcamento_data,new.data_pedido) is distinct from coalesce(old.orcamento_data,old.data_pedido) or
   (new.data_pedido is distinct from old.data_pedido and not conversao)) then raise exception 'Remova os itens antes de alterar a loja ou data base da cotação';end if;
 end if;
 if new.modalidade_venda='intermediacao' then new.frete_volume_opcao:='dispensar';new.frete_volume_ativo:=false;new.frete_volume_valor:=0;new.frete_volume_detalhes:='[]';end if;
 return new;
end $function$
